  const amrex::Real x55 = x54 / x19;
  amrex::Real x61 = kf_qss[301] + kf_qss[313] * sc[3] + 10.0e-13;
  const amrex::Real x62 = (1.0 / ((-kf_qss[348] - kf_qss[359] + 10.0e-13)));
